{"filePath": "c:\Users\eldno\chthonic-archive\src\data\lore_types.rs", "content": "//! Lore overlay types — authored content from game/lore/**/*.json
//!
//! @SID:    LORE_TYPES_V1
//! @Shabti: Type System — Lore Overlay Layer
//!
//! These types parallel the flat `Entity` struct in types.rs.
//! They carry the deep authored content (combat abilities, spectral chains,
//! faction bonuses) that has no home in the flat persistence schema.
//! Loaded by lore_loader.rs, merged into FactionRegistry at init time.

use serde::{Deserialize, Serialize};

// ── Character overlay ────────────────────────────────────────────────────────

/// A single combat ability authored in `game/lore/characters/*.json`.
/// `status` is flexible — can be a string or an array of strings in JSON.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CombatAbility {
    pub id: String,
