use anyhow::{Context, Result};
use std::fs;
use std::path::Path;

use super::lore_types::{
    LoreCharacterOverlay, LorePrimeFactionEntry, LorePrimeFactionsFile, LoreTriumvirate,
};

/// Scan `{game_root}/lore/characters/*.json` and deserialise each file as a
/// `LoreCharacterOverlay`. Unknown extra fields are ignored (serde default).
pub fn load_lore_characters(game_root: &str) -> Result<Vec<LoreCharacterOverlay>> {
    let dir = Path::new(game_root).join("lore").join("characters");
    if !dir.exists() {
        return Ok(Vec::new());
    }
    let mut out = Vec::new();
    for entry in fs::read_dir(&dir).with_context(|| format!("read lore/characters dir: {}", dir.display()))? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().and_then(|s| s.to_str()) != Some("json") {
            continue;
        }
        let content = fs::read_to_string(&path)
            .with_context(|| format!("read lore char: {}", path.display()))?;
        let overlay: LoreCharacterOverlay = serde_json::from_str(&content)
            .with_context(|| format!("parse lore char: {}", path.display()))?;
        out.push(overlay);
    }
    Ok(out)
}

