            let path = entry.path();
            if path.extension().and_then(|s| s.to_str()) != Some("json") {
                continue;
            }

            let content = fs::read_to_string(&path)
                .with_context(|| format!("Failed to read game schema {}", path.display()))?;
            let value: Value = serde_json::from_str(&content)
                .with_context(|| format!("Failed to parse game schema {}", path.display()))?;

            // Try multiple title keys — lore files use "name" or a top-level "title";
            // fall back to the file stem so the entry is always human-readable.
            let title = value
                .get("name")
                .or_else(|| value.get("title"))
                .and_then(Value::as_str)
                .or_else(|| path.file_stem().and_then(|s| s.to_str()))
                .unwrap_or("Untitled")
                .to_string();

            let id = value
                .get("$id")
                .or_else(|| value.get("faction_id"))
                .or_else(|| value.get("character_id"))
                .and_then(Value::as_str)
                .map(ToString::to_string);

            docs.push(GameSchemaDocument {
                title,
                id,
                path,
                domain: domain.clone(),
            });
        }
    }

    Ok(docs)
}

