pub fn load_game_schema_documents<P: AsRef<Path>>(root: P) -> Result<Vec<GameSchemaDocument>> {
    let root = root.as_ref();
    let targets = [
        root.join("dialogue").join("dialogue.schema.json"),
        root.join("systems").join("combat.schema.json"),
        root.join("design").join("quests.schema.json"),
    ];

    let mut docs = Vec::new();
    for path in targets {
        if !path.exists() {
            continue;
        }

        let content = fs::read_to_string(&path)
            .with_context(|| format!("Failed to read game schema {}", path.display()))?;
        let value: Value = serde_json::from_str(&content)
            .with_context(|| format!("Failed to parse game schema {}", path.display()))?;

        let title = value
            .get("title")
            .and_then(Value::as_str)
            .unwrap_or("Untitled Schema")
            .to_string();

        let id = value.get("$id").and_then(Value::as_str).map(ToString::to_string);
        let domain = path
            .parent()
            .and_then(Path::file_name)
            .and_then(|name| name.to_str())
            .unwrap_or("unknown")
            .to_string();

        docs.push(GameSchemaDocument {
            title,
            id,
            path,
            domain,
        });
    }

    Ok(docs)
}

