      const vec = `${CYAN}${row.spin_vector}${R}`;
      const titleStr = row.title.length > 44 ? row.title.slice(0, 41) + "…" : row.title;
      console.log(`  ${d}  [${row.task_id}]  ${vec}  ${titleStr}`);
